"""Draft for Selective Compulsory Book 1, Chapters 1–2 (People's Education Press, 2019): conservation of momentum and mechanical oscillation."""
from phy_hs_lib import T, C, N

# ================= Chapter 1: Conservation of Momentum =================
T("momentum", "Motion and interactions", "conceptual",
  "Momentum is the product of mass and velocity, p = mv. It is a vector in the direction of velocity, with SI unit kg·m/s. The change in momentum, Δp = p′ − p, is also a vector. For one-dimensional problems, choose a positive direction before using signed values. Momentum is related to kinetic energy by Ek = p²/(2m).",
  ["Write the definition of momentum and state that it is a vector", "Choose a positive direction and calculate momentum and its change in one dimension", "Distinguish momentum from kinetic energy and compare them using Ek = p²/(2m)"],
  [("S1.1.1", "exact")],
  pre=[("velocity", "hard"), ("newton2", "soft"), ("kinetic_energy", "soft"), ("J:speed", "soft")],
  qs=[
    C("basic", "Which statement about momentum is correct?",
      "Momentum is a vector in the same direction as an object's velocity",
      ["Momentum is a scalar with magnitude but no direction", "Momentum always points in the same direction as an object's acceleration", "Momentum always points in the same direction as the net force on an object"],
      "In p = mv, mass is a positive scalar, so momentum points in the direction of velocity. Acceleration and net force determine the direction of the change in velocity (momentum), which need not match the momentum direction."),
    N("basic", "A 500 g ball moves at 36 km/h. What is the magnitude of its momentum in kg·m/s? (Enter the number only.)", "5",
      "Convert to SI units: m = 0.5 kg and v = 36 km/h = 10 m/s. Then p = mv = 0.5 × 10 = 5 kg·m/s. Substituting without converting units would give 18 or 18000.",
      "round(0.5*36/3.6,6)"),
    C("standard", "A 0.2 kg ball moves at 6 m/s perpendicular to a vertical wall and rebounds in the opposite direction at 4 m/s. Take its initial direction as positive. What is the ball's change in momentum?",
      "-2.0 kg·m/s",
      ["-0.4 kg·m/s", "2.0 kg·m/s", "0.4 kg·m/s"],
      "Before impact, p = 0.2 × 6 = 1.2 kg·m/s. After impact, velocity is reversed, so p′ = 0.2 × (−4) = −0.8 kg·m/s and Δp = p′ − p = −2.0 kg·m/s. Subtracting the speeds directly would give ±0.4 and ignore direction.",
      verify="round(0.2*(-4)-0.2*6,6)"),
    C("standard", "Objects A and B have equal kinetic energy and mass ratio mA:mB = 4:1. What is the ratio pA:pB of their momentum magnitudes?",
      "2 : 1",
      ["4 : 1", "1 : 2", "16 : 1"],
      "From Ek = p²/(2m), p = √(2mEk). For equal kinetic energies, p is proportional to √m, so pA:pB = √4:√1 = 2:1. Treating p as proportional to m would give 4:1."),
  ], root=None)

T("impulse", "Motion and interactions", "conceptual",
  "Impulse is the product of force and the time it acts, I = Ft. It is a vector in the direction of a constant force, with unit N·s. Impulse describes the accumulated effect of force over time and is independent of whether the object is moving. The area between an F-t graph and the time axis represents impulse.",
  ["Write the constant-force impulse formula I = Ft and determine its direction", "Know that a force has impulse even when the object is at rest", "Find impulse from the area under an F-t graph and calculate net impulse"],
  [("S1.1.1", "exact")],
  pre=[("momentum", "hard"), ("newton2", "hard"), ("force_decompose", "soft"), ("J:force", "soft")],
  qs=[
    C("basic", "Which statement about impulse is correct?",
      "Impulse is a vector; the impulse of a constant force points in the direction of that force",
      ["Impulse always points in the direction of an object's motion", "A greater force always produces a greater impulse", "Impulse is a scalar with magnitude but no direction"],
      "In I = Ft, time t is a positive scalar, so the impulse of a constant force points in the force's direction, regardless of the object's motion. Impulse also depends on how long the force acts, so a large force acting briefly need not produce a large impulse."),
    N("basic", "A 2 kg object rests on a horizontal table for 5 s. What is the magnitude of the impulse of gravity during this time, in N·s? (Take g = 10 m/s²; enter the number only.)", "100",
      "Gravity is G = mg = 20 N, so I = Gt = 20 × 5 = 100 N·s. The object being at rest does not make the force's impulse zero; a force acting over time produces impulse.",
      "2*10*5"),
    C("standard", "A force increases uniformly from F = 0 at t = 0 to F = 10 N at t = 4 s, without changing direction. What is the magnitude of its impulse during the 4 s?",
      "20 N·s",
      ["40 N·s", "10 N·s", "2.5 N·s"],
      "The F-t graph is a straight line through the origin, so the impulse is the triangular area: I = ½ × 4 × 10 = 20 N·s. Omitting the factor ½ would give 40 N·s.",
      verify="0.5*4*10"),
    C("standard", "A 1 kg object slides from rest for 2 s down a smooth fixed incline at 30°. Take g = 10 m/s², sin30° = 0.5, and cos30° ≈ 0.87. What is the magnitude of the net impulse on the object during this time?",
      "10 N·s",
      ["20 N·s", "17.4 N·s", "5 N·s"],
      "On the smooth incline, the net force is mg sin30° = 5 N, so the net impulse is 5 × 2 = 10 N·s down the incline. 20 N·s is the impulse of gravity; 17.4 N·s results from incorrectly using cos30°.",
      verify="1*10*0.5*2"),
  ])

T("momentum_theorem", "Motion and interactions", "procedural",
  "Momentum theorem: the impulse of the net external force on an object equals its change in momentum, I_net = Δp, or F_net t = mv′ − mv. This is a vector equation; choose a positive direction for one-dimensional problems. Explain cushioning and impacts: for the same change in momentum, a longer interaction time means a smaller average force.",
  ["State the momentum theorem and explain that impulse must be due to the net force", "Use the momentum theorem in one dimension to find velocity or average force", "Use the momentum theorem to explain cushioning and impacts"],
  [("S1.1.1", "exact")],
  pre=[("impulse", "hard"), ("momentum", "hard"), ("newton2", "hard"), ("work_energy_theorem", "soft")],
  qs=[
    C("basic", "Which statement correctly describes the momentum theorem?",
      "The impulse of the net external force on an object equals its change in momentum",
      ["The impulse of any one force on an object equals its change in momentum", "The work done by the net force equals the object's change in momentum", "The impulse of the net force equals the object's final momentum"],
      "The impulse in the momentum theorem is due to the net force and equals the change in momentum Δp, not the final momentum. Work done by the net force corresponds to a change in kinetic energy."),
    N("basic", "A 2 kg object at rest on a smooth horizontal surface moves under a constant horizontal force of 6 N for 3 s. What is its final speed in m/s? (Enter the number only.)", "9",
      "From Ft = mv − 0, v = Ft/m = 6 × 3 / 2 = 9 m/s. Omitting the mass and using Ft directly would give 18.",
      "6*3/2"),
    C("standard", "The same egg is dropped from the same height onto a hard floor and a foam pad. It has the same speed on impact and stops in both cases. Why is it less likely to break on the foam pad?",
      "The change in momentum is the same, but the foam lengthens the stopping time and reduces the average force",
      ["The foam reduces the egg's change in momentum", "The foam reduces the impulse of the net force on the egg", "The foam exerts less force on the egg than the egg exerts on the foam"],
      "The egg has the same Δp in both cases, so the net impulse F t = Δp is also the same. The foam increases the interaction time, reducing the average force. The forces two objects exert on each other are equal and opposite, so claiming that the foam's force on the egg is smaller would violate Newton's third law."),
    N("advanced", "A 60 kg construction worker accidentally falls from a height. The safety harness tightens after a 5 m free fall, then brings the worker to rest in 1.5 s. Take g = 10 m/s². What is the magnitude of the harness's average upward force on the worker, in N? (Enter the number only.)", "1000",
      "The speed when the harness tightens is v = √(2gh) = 10 m/s. Take upward as positive and apply the momentum theorem during the stopping interval: (F − mg)t = 0 − (−mv), so F = mg + mv/t = 600 + 60×10/1.5 = 1000 N. Ignoring gravity and using only mv/t would give 400 N.",
      "round(60*10+60*sqrt(2*10*5)/1.5,6)"),
  ])

T("momentum_conservation", "Motion and interactions", "procedural",
  "A system's total momentum remains constant if it experiences no external force or if the vector sum of external forces is zero. Momentum is also approximately conserved during a short process, such as a collision or explosion, when internal forces greatly exceed external forces. Choose the system, check the conditions, set a positive direction, and solve using m1v1 + m2v2 = m1v1′ + m2v2′.",
  ["Determine whether momentum is conserved in a process", "Choose a positive direction and write a conservation equation to find an unknown velocity", "Know that momentum conservation is independent of whether mechanical energy is conserved"],
  [("S1.1.1", "exact"), ("S1.1.3", "inferred")],
  pre=[("momentum_theorem", "hard"), ("newton3", "hard"), ("energy_conservation", "soft")],
  qs=[
    C("basic", "Under what condition is momentum conserved?",
      "The system has no external force, or the vector sum of the external forces is zero",
      ["The objects within the system do not interact", "The total work done by external forces is zero", "The system's mechanical energy is conserved"],
      "Momentum conservation depends on whether the vector sum (net force) of external forces is zero; internal forces occur in equal-and-opposite pairs whose impulses cancel. Zero external work or conservation of mechanical energy does not necessarily imply momentum conservation."),
    N("basic", "A 60 kg person jumps at 4 m/s horizontally onto a 20 kg cart at rest on a smooth horizontal surface. What is their speed after they move together, in m/s? (Enter the number only.)", "3",
      "There is no net horizontal external force, so momentum is conserved: 60 × 4 = (60 + 20)v, giving v = 3 m/s.",
      "60*4/(60+20)"),
    C("standard", "In which situation is momentum conserved for the chosen system?",
      "Two balls collide on a smooth horizontal surface; the system consists of both balls",
      ["A spring attached to a vertical wall launches a block; the system consists of the block and spring", "A block slides down a smooth fixed incline; the system consists of the block alone", "A ball is thrown vertically upward; the system consists of the ball alone"],
      "The two-ball system has no external horizontal force, and gravity is balanced by the support force vertically, so its net external force is zero. In the other cases, the spring experiences an external force from the wall, the block on the incline has a nonzero resultant of gravity and support, and the upward-thrown ball is acted on by gravity."),
    N("standard", "On a smooth horizontal surface, a 2 kg object moves right at 5 m/s and a 3 kg object moves left at 2 m/s. They collide and stick together. Take right as positive. What is their velocity after the collision in m/s? (Enter the number only.)", "0.8",
      "Take right as positive: 2 × 5 + 3 × (−2) = (2 + 3)v, so v = 4/5 = 0.8 m/s, positive (to the right). Treating the second object's velocity as +2 would give 3.2.",
      "(2*5-3*2)/(2+3)"),
  ])

T("exp_momentum", "Motion and interactions", "procedural",
  "Verify momentum conservation using an air track with photogates or a ramp with projectile-motion balls. The key is to make the net external force on the system approximately zero (level the air track and the end of the ramp), measure the masses and velocities before and after the collision (or quantities that can replace velocity), and compare m1v1 + m2v2 with m1v1′ + m2v2′.",
  ["Explain why the air track must be level and calculate velocity from a flag width and photogate time", "Explain how horizontal displacement can replace velocity in the projectile method and write the verification equation", "Process experimental data and determine whether momentum is conserved"],
  [("S1.X.1", "exact"), ("S1.1.1", "inferred")],
  pre=[("momentum_conservation", "hard"), ("projectile", "soft"), ("exp_vt", "soft")],
  qs=[
    C("basic", "When using an air track and photogates to verify momentum conservation, why should the track be leveled before the experiment?",
      "To make the net horizontal force on the gliders approximately zero so momentum is conserved for the two-glider system",
      ["To make the gliders move with constant acceleration along the track", "To conserve mechanical energy before and after the collision", "To make the two gliders have equal masses"],
      "A level air track has very little friction, making the net force along the track approximately zero and allowing the system's momentum to be conserved. Constant acceleration, mechanical-energy conservation, and equal masses are not the reason for leveling it."),
    N("basic", "A flag on a glider is 2.0 cm wide. It blocks a photogate for 0.010 s. What is the glider's speed at the photogate, in m/s? (Enter the number only.)", "2",
      "The flag is narrow, so its average speed approximates the instantaneous speed: v = d/Δt = 0.020 m / 0.010 s = 2.0 m/s. Failing to convert centimeters to meters would give 200.",
      "0.020/0.010"),
    C("standard", "In a ramp-based projectile experiment, an incoming ball of mass m1 is released from the same point each time. Without a second ball, it lands at P. With a target ball of mass m2 (m1 > m2) present, they collide head-on; the incoming ball lands at M and the target ball at N. O is the point on the ground directly below the end of the ramp. Neglect ball radii, and assume the balls do not stick together. Which equation should be checked to verify momentum conservation?",
      "m1·OP = m1·OM + m2·ON",
      ["m1·OM = m1·OP + m2·ON", "m1·OP = m1·OM − m2·ON", "m1·OP = (m1 + m2)·ON"],
      "The balls fall through the same height for the same time. Since horizontal displacement x = vt is proportional to velocity, horizontal distance can replace velocity: m1v0 = m1v1 + m2v2, or m1·OP = m1·OM + m2·ON. The equation m1·OP = (m1 + m2)·ON applies when the balls stick together, which they do not in this experiment."),
    N("advanced", "In the projectile method for verifying momentum conservation, m1 = 30 g, m2 = 10 g, OP = 25.0 cm, and OM = 15.0 cm. If momentum is conserved, what should the target ball's horizontal range ON be, in cm? (Enter the number only.)", "30",
      "From m1·OP = m1·OM + m2·ON, ON = m1(OP − OM)/m2 = 30 × (25.0 − 15.0)/10 = 30 cm. Using grams for mass is fine as long as the units match on both sides.",
      "30*(25.0-15.0)/10"),
  ])

T("collision", "Motion and interactions", "conceptual",
  "A collision lasts for a very short time, so internal forces greatly exceed external forces and system momentum is conserved. Collisions are classified by kinetic-energy loss: elastic (kinetic energy is unchanged), inelastic (kinetic energy decreases), and perfectly inelastic (the objects stick together and move at the same velocity, with the greatest kinetic-energy loss).",
  ["Distinguish elastic, inelastic, and perfectly inelastic collisions", "Know that momentum is conserved and kinetic energy does not increase in collisions", "Calculate kinetic-energy loss during a collision"],
  [("S1.1.2", "exact")],
  pre=[("momentum_conservation", "hard"), ("kinetic_energy", "hard"), ("J:mech_energy", "soft")],
  qs=[
    C("basic", "Which statement about collisions is correct?",
      "The system's total kinetic energy is unchanged in an elastic collision",
      ["The system's total momentum is not conserved in an inelastic collision", "The system's total kinetic energy must decrease in every collision", "A perfectly inelastic collision has the smallest kinetic-energy loss"],
      "If a collision is very brief and external forces are negligible, momentum is conserved in every type of collision. Kinetic energy is unchanged in an elastic collision, decreases in an inelastic collision, and has the greatest loss in a perfectly inelastic collision, where the objects move together afterward."),
    C("basic", "Two objects collide head-on on a smooth horizontal surface. The system's total kinetic energy is 20 J before the collision and 16 J afterward. What type of collision is this?",
      "An inelastic collision with a loss of kinetic energy",
      ["An elastic collision", "A collision in which system momentum is not conserved", "An impossible collision, because kinetic energy cannot decrease"],
      "Kinetic energy decreases by 4 J, so the collision is inelastic. There is no net horizontal external force, so momentum is still conserved. Kinetic energy may stay the same or decrease during a collision."),
    C("standard", "On a smooth horizontal surface, block A moves right at speed v toward stationary block B, which has a light spring on its left side. A compresses the spring. What is true when the spring is compressed the most?",
      "A and B have the same velocity, and the system's elastic potential energy is greatest",
      ["A and B are both at rest", "The system's total momentum is smallest", "The system's elastic potential energy is smallest"],
      "At maximum compression, the blocks have no relative motion and share a velocity. The system's kinetic energy is then smallest and its elastic potential energy greatest. System momentum is conserved and nonzero throughout, so both blocks cannot be at rest."),
    N("standard", "On a smooth horizontal surface, a 2 kg object moving at 3 m/s collides with a stationary 1 kg object, and they stick together. How much kinetic energy is lost, in J? (Enter the number only.)", "3",
      "Momentum is conserved: 2 × 3 = 3v, so v = 2 m/s. The kinetic-energy loss is ΔEk = ½ × 2 × 3² − ½ × 3 × 2² = 9 − 6 = 3 J. Omitting the struck object's final kinetic energy and using only ½ × 2 × 2² = 4 J would incorrectly give 5 J.",
      "0.5*2*3**2-0.5*3*2**2"),
  ])

T("collision_analysis", "Motion and interactions", "reasoning",
  "For a one-dimensional elastic collision in which m1 moving at v1 strikes stationary m2, v1′ = (m1 − m2)v1/(m1 + m2) and v2′ = 2m1v1/(m1 + m2); equal masses exchange velocities. A perfectly inelastic collision has the greatest kinetic-energy loss. To judge whether a collision outcome is possible, check momentum conservation, that kinetic energy does not increase, and that the post-collision velocities are reasonable.",
  ["Use one-dimensional elastic-collision formulas to find final velocities and discuss the effect of mass", "Know that a perfectly inelastic collision has maximum kinetic-energy loss and judge whether an outcome is possible", "Analyze collisions using momentum, energy, and motion"],
  [("S1.1.2", "exact"), ("S1.1.3", "inferred")],
  pre=[("collision", "hard"), ("energy_conservation", "soft"), ("work_energy_theorem", "soft")],
  qs=[
    N("basic", "Two 2 kg balls collide elastically head-on on a smooth horizontal surface. Before the collision, one moves at 4 m/s and the other is stationary. What is the final speed of the ball that was initially at rest, in m/s? (Enter the number only.)", "4",
      "v2′ = 2m1v1/(m1 + m2) = 2 × 2 × 4/(2 + 2) = 4 m/s, and v1′ = 0; the balls exchange velocities.",
      "2*2*4/(2+2)"),
    C("basic", "A ball of mass m1 moving at v0 collides elastically head-on with a stationary ball of mass m2, where m1 < m2. What happens to ball 1 after the collision?",
      "It rebounds in the opposite direction",
      ["It continues in the same direction at a lower speed", "It stops", "It continues in the same direction at the same speed"],
      "v1′ = (m1 − m2)v0/(m1 + m2) is negative when m1 < m2, so ball 1 rebounds. It stops only when m1 = m2; when m1 > m2, it continues forward."),
    N("standard", "On a smooth horizontal surface, a 1 kg ball moving right at 6 m/s collides elastically head-on with a stationary 2 kg ball. Take right as positive. What is the velocity of the 1 kg ball after the collision, in m/s? (Enter a negative number for motion to the left.)", "-2",
      "v1′ = (m1 − m2)v1/(m1 + m2) = (1 − 2) × 6/3 = −2 m/s; the negative sign means left. The other ball has v2′ = 2 × 1 × 6/3 = 4 m/s.",
      "(1-2)/(1+2)*6"),
    C("advanced", "On a smooth horizontal surface, ball A (mass 1 kg) moving at 6 m/s catches up with ball B (mass 2 kg) moving in the same direction at 2 m/s, and they collide head-on. Which set of final velocities is possible?",
      "vA′ = 2 m/s, vB′ = 4 m/s",
      ["vA′ = 4 m/s, vB′ = 3 m/s", "vA′ = −2 m/s, vB′ = 6 m/s", "vA′ = 0, vB′ = 5 m/s"],
      "Initial total momentum is 1×6 + 2×2 = 10 kg·m/s, and total kinetic energy is 22 J. All four options conserve momentum. For vA′=2 and vB′=4, kinetic energy is 18 J and A does not pass through B, so the result is possible. With vA′=4 and vB′=3, A would still be faster than B and pass through it. The other two choices give kinetic energies of 38 J and 25 J, both greater than the initial 22 J, so they are impossible."),
  ])

T("recoil", "Motion and interactions", "application",
  "When a stationary object ejects part of itself in one direction, the remainder moves in the opposite direction; this recoil follows from momentum conservation. A rocket gains forward velocity by expelling gas backward at high speed, so it can fly in a vacuum. A greater exhaust speed and mass ratio give the rocket a greater velocity.",
  ["Identify recoil and use momentum conservation to find recoil velocity", "Find a rocket's velocity as it expels gas", "Explain how a rocket works"],
  [("S1.1.1", "exact"), ("S1.1.3", "inferred")],
  pre=[("momentum_conservation", "hard"), ("newton3", "soft")],
  qs=[
    C("basic", "Which of the following is an example of recoil?",
      "A rocket flies forward by expelling high-speed gas backward",
      ["A car accelerates on a road", "An athlete jumps by pushing against the ground", "A person pushes a cart forward"],
      "In recoil, one part of a system moves in one direction and another part moves in the opposite direction. A car accelerates due to friction from the road, a jump uses the ground's support force, and pushing a cart uses friction from the ground; each involves an external force."),
    N("basic", "A 50 kg person is at rest on smooth ice and throws a 2 kg object horizontally forward at 10 m/s relative to the ground. What is the magnitude of the person's recoil speed, in m/s? (Enter the number only.)", "0.4",
      "Horizontal momentum is conserved: 0 = 2 × 10 − 50v, so v = 0.4 m/s, opposite the object's direction.",
      "2*10/50"),
    N("standard", "A rocket with total mass 500 kg is at rest in space and instantly ejects 20 kg of gas backward. The gas's speed relative to the ground (inertial frame) is 240 m/s. What is the rocket's speed after the gas is expelled, in m/s? (Enter the number only.)", "10",
      "Take the rocket's forward direction as positive. Momentum conservation gives 0 = (500 − 20)v − 20 × 240, so v = 4800/480 = 10 m/s. The rocket's mass after expelling the gas is 480 kg, not 500 kg; using 500 would give 9.6.",
      "20*240/(500-20)"),
    C("standard", "Which statement about rocket flight is correct?",
      "A rocket can fly in a vacuum; it gains thrust by recoiling as it expels gas backward",
      ["A rocket gets thrust by pushing on the surrounding air and cannot fly in a vacuum", "With all else equal, a higher exhaust speed gives the rocket a lower speed", "A rocket's mass remains constant during flight"],
      "Momentum is conserved for the system consisting of the rocket and expelled gas. Thrust comes from the reaction to the gas, so air is not needed. A higher exhaust speed gives the rocket a greater speed, and the rocket's mass decreases as fuel is expelled."),
  ])

# ================= Chapter 2: Mechanical Oscillation =================
T("shm", "Motion and interactions", "conceptual",
  "Mechanical oscillation is back-and-forth motion about an equilibrium position. A spring oscillator is an idealized model whose displacement is measured from equilibrium. The restoring force always points toward equilibrium, and acceleration increases with displacement. Motion with a sinusoidal (or cosinusoidal) displacement-time graph is simple harmonic motion, which has symmetry.",
  ["Know that a spring oscillator's displacement is measured from equilibrium and distinguish equilibrium from the spring's natural-length position", "Analyze displacement, velocity, and acceleration at maximum displacement and at equilibrium", "Know that the displacement-time graph of simple harmonic motion is sinusoidal"],
  [("S1.2.1", "exact")],
  pre=[("elastic_force", "hard"), ("acceleration", "soft"), ("J:sound_source", "soft")],
  qs=[
    C("basic", "For a spring oscillator in simple harmonic motion, what does its displacement mean?",
      "Its displacement from equilibrium, directed from the equilibrium position to the oscillator's current position",
      ["Its displacement from its release point to its current position", "Its displacement from the spring's natural length, regardless of orientation", "The distance the oscillator travels during a time interval"],
      "Displacement in simple harmonic motion is always measured from equilibrium. For a vertically suspended spring oscillator, the spring is stretched at equilibrium and is not at its natural length. Distance traveled is a scalar, not displacement."),
    C("basic", "A horizontal spring oscillator reaches its maximum displacement. What are its velocity and acceleration?",
      "Its velocity is zero and its acceleration is greatest",
      ["Its velocity is greatest and its acceleration is zero", "Both its velocity and acceleration are greatest", "Both its velocity and acceleration are zero"],
      "At maximum displacement, the spring is stretched or compressed the most, so the restoring force and acceleration are greatest. The oscillator is about to reverse direction, so its velocity is zero. At equilibrium, the reverse is true: velocity is greatest and acceleration is zero."),
    C("standard", "A horizontal spring oscillator moves from maximum displacement toward equilibrium. Which statement is correct?",
      "Displacement decreases, speed increases, and acceleration decreases",
      ["Displacement decreases, speed decreases, and acceleration decreases", "Displacement decreases, speed increases, and acceleration increases", "Displacement decreases, speed decreases, and acceleration increases"],
      "Restoring force and acceleration are proportional to displacement and point toward equilibrium. As displacement decreases, acceleration decreases; acceleration is in the direction of velocity, so speed increases and is greatest at equilibrium."),
    N("standard", "A light spring with spring constant 100 N/m is fixed at the top and supports a 0.5 kg oscillator that moves vertically in simple harmonic motion. Take g = 10 m/s². How far is the spring stretched at equilibrium, in cm? (Enter the number only.)", "5",
      "The net restoring force is zero at equilibrium: kx0 = mg, so x0 = mg/k = 0.5 × 10/100 = 0.05 m = 5 cm. The equilibrium position of a vertical spring is not its natural-length position.",
      "round(0.5*10/100*100,6)"),
  ])

T("shm_describe", "Motion and interactions", "procedural",
  "Simple harmonic motion is described by amplitude A, period T, frequency f = 1/T, and phase. Displacement can be written as x = A sin(ωt + φ), where ω = 2π/T = 2πf, ωt + φ is the phase, and φ is the initial phase. The oscillator travels a distance of 4A in one period.",
  ["Explain amplitude, period, frequency, and phase, and know that ω = 2π/T", "Read amplitude, period, and initial phase from x = A sin(ωt + φ) and calculate displacement at a given time", "Compare the frequencies and phase difference of two simple harmonic motions"],
  [("S1.2.1", "exact")],
  pre=[("shm", "hard"), ("circular", "soft"), ("J:sound_feature", "soft")],
  math=[("cnm_h066", "x = A sin(ωt + φ) is a sine function; amplitude, period, and initial phase correspond to the graph's extrema, period, and horizontal shift."),
        ("cnm_h057", "The phase ωt + φ is measured in radians.")],
  qs=[
    C("basic", "Which statement about the amplitude of simple harmonic motion is correct?",
      "Amplitude is a scalar equal to the oscillator's maximum distance from equilibrium",
      ["Amplitude is the oscillator's displacement, which changes continuously with time", "Amplitude equals the distance traveled in one period", "A greater amplitude means a longer period"],
      "Amplitude is a scalar measure of oscillation size, equal to the magnitude of the maximum displacement, and does not change with time. The distance traveled in one period is 4A. A spring oscillator's period is T = 2π√(m/k), independent of amplitude."),
    N("basic", "A simple harmonic motion has displacement x = 5 sin(4πt + π/2) cm. What is its period in seconds? (Enter the number only.)", "0.5",
      "ω = 4π rad/s, so T = 2π/ω = 2π/(4π) = 0.5 s. Treating 4π as the frequency f would incorrectly give T = 1/(4π) ≈ 0.08 s.",
      "2*pi/(4*pi)"),
    N("standard", "A simple harmonic motion has displacement x = 8 sin(πt + π/6) cm. What is its displacement at t = 1 s, in cm? (Enter a negative number for the negative direction.)", "-4",
      "The phase is π·1 + π/6 = 7π/6, and sin(7π/6) = −1/2, so x = 8 × (−1/2) = −4 cm. The oscillator is on the negative side of equilibrium.",
      "round(8*sin(pi*1+pi/6),6)"),
    C("standard", "Two simple harmonic motions have displacements x1 = 3 sin(100πt + π/3) cm and x2 = 5 sin(100πt + π/6) cm. Which statement is correct?",
      "Both have frequency 50 Hz, and their phase difference is π/6",
      ["Both have frequency 100 Hz, and their phase difference is π/6", "Both have frequency 50 Hz, and their phase difference is π/2", "Both have frequency 100π Hz, and their phase difference is π/3"],
      "ω = 100π rad/s, so f = ω/(2π) = 50 Hz; confusing ω with f is a common error. The phase difference is the difference between the phases. Since the ωt terms are the same, it is π/3 − π/6 = π/6."),
  ])

T("shm_force_energy", "Motion and interactions", "reasoning",
  "In simple harmonic motion, the restoring force is F = −kx: its magnitude is proportional to displacement and it always points toward equilibrium. Kinetic and potential energy transform into each other; without energy loss, total mechanical energy remains constant, E = ½kA². Greater amplitude means greater energy. A spring oscillator's period T = 2π√(m/k) is independent of amplitude.",
  ["Explain the minus sign in F = −kx and calculate restoring force", "Use energy conservation to analyze kinetic-potential energy transfer and find maximum speed at equilibrium", "Know how total energy depends on amplitude and that period is independent of amplitude"],
  [("S1.2.1", "exact")],
  pre=[("shm_describe", "hard"), ("newton2", "hard"), ("elastic_force", "soft"), ("energy_conservation", "soft")],
  qs=[
    C("basic", "In the restoring-force equation F = −kx for simple harmonic motion, what does the minus sign mean?",
      "The restoring force points opposite the displacement, toward equilibrium",
      ["The restoring force always points opposite the velocity", "The restoring-force magnitude decreases as displacement increases", "The restoring force always does negative work on the oscillator"],
      "x is displacement from equilibrium, and F points opposite x, toward equilibrium. Restoring-force magnitude is proportional to displacement. It does negative work as the oscillator moves away from equilibrium and positive work as it moves toward equilibrium, so it does not always do negative work."),
    N("basic", "A spring oscillator has spring constant 200 N/m and is displaced 3 cm from equilibrium. What is the magnitude of the restoring force in N? (Enter the number only.)", "6",
      "F = kx = 200 × 0.03 = 6 N. Convert 3 cm to 0.03 m; otherwise the result would be 600.",
      "200*0.03"),
    C("standard", "A horizontal spring oscillator undergoes simple harmonic motion. If its amplitude is doubled, how does its total mechanical energy change?",
      "4 times",
      ["2 times", "Unchanged", "√2 times"],
      "Total mechanical energy equals the elastic potential energy at maximum displacement, E = ½kA², and is proportional to A². Doubling A makes E four times as large. (The period remains unchanged because it is independent of amplitude.)",
      verify="2**2"),
    N("advanced", "A horizontal spring oscillator has mass 0.1 kg, spring constant 40 N/m, and amplitude 5 cm. Neglect resistance. What is its speed as it passes equilibrium, in m/s? (Enter the number only.)", "1",
      "By conservation of mechanical energy, ½kA² = ½mv², so v = A√(k/m) = 0.05 × √(40/0.1) = 0.05 × 20 = 1 m/s. Convert the 5 cm amplitude to 0.05 m first.",
      "round(0.05*sqrt(40/0.1),6)"),
  ])

T("pendulum", "Motion and interactions", "reasoning",
  "For a small angle (generally less than 5°), the restoring force of a simple pendulum is approximately F = −(mg/l)x, so the bob undergoes simple harmonic motion. Its period is T = 2π√(l/g), determined by length l and local gravitational acceleration g, and independent of the bob's mass and amplitude.",
  ["Know the condition for simple harmonic motion of a pendulum and the source of its restoring force", "Calculate period with T = 2π√(l/g) and compare periods under different conditions", "Know that a simple pendulum's period is independent of bob mass and amplitude"],
  [("S1.2.2", "exact")],
  pre=[("shm_force_energy", "hard"), ("force_decompose", "hard"), ("gravity", "soft")],
  math=[("cnm_h057", "For a small pendulum angle measured in radians, sinθ ≈ θ, so the restoring force is approximately proportional to displacement.")],
  qs=[
    N("basic", "A simple pendulum of length 1.00 m swings through a small angle where g = 10 m/s². Take π² = 10. What is its period in seconds? (Enter the number only.)", "2",
      "T = 2π√(l/g) = 2π√(1/10). Since π = √10, T = 2√10 × √(1/10) = 2 s.",
      "round(2*sqrt(10)*sqrt(1.0/10),6)"),
    C("basic", "For a simple pendulum swinging through a small angle, what determines its period?",
      "Its length and the local gravitational acceleration",
      ["The bob's mass and the pendulum's length", "The amplitude of the swing", "The bob's mass and the local gravitational acceleration"],
      "T = 2π√(l/g), so the period depends only on length l and gravitational acceleration g, not on the bob's mass or amplitude."),
    C("standard", "The same pendulum, with unchanged length, is moved from Earth to a planet where gravitational acceleration is one-quarter of Earth's. Its angle remains small. How does its period compare with its period on Earth?",
      "2 times",
      ["4 times", "0.5 times", "16 times"],
      "T is proportional to √(1/g). When g becomes 1/4 as large, T increases by 1/√(1/4) = 2. Treating T as inversely proportional to g would give 4; reversing the square root would give 0.5; 16 results from using a square instead.",
      verify="1/sqrt(1/4)"),
    N("advanced", "A simple pendulum has a period of 2 s in a stationary elevator. The elevator then accelerates downward at 7.5 m/s². Take g = 10 m/s² and assume a small swing angle. What is the pendulum's period now, in seconds? (Enter the number only.)", "4",
      "With the elevator accelerating downward, the effective gravitational acceleration is g′ = g − a = 2.5 m/s². T′/T = √(g/g′) = √(10/2.5) = 2, so T′ = 4 s.",
      "2*sqrt(10/(10-7.5))"),
  ])

T("exp_pendulum", "Motion and interactions", "procedural",
  "Measure gravitational acceleration using a simple pendulum: from T = 2π√(l/g), find g = 4π²l/T², or plot T² against l, with slope k = 4π²/g and g = 4π²/k. Measure pendulum length as string length plus bob radius, keep the angle below 5°, start timing at the lowest point, and time multiple complete oscillations to find the period.",
  ["Measure pendulum length and period correctly", "Find gravitational acceleration from the slope of a T²–l graph", "Analyze how errors in pendulum length affect the graph and result"],
  [("S1.X.2", "exact"), ("S1.2.2", "inferred")],
  pre=[("pendulum", "hard"), ("exp_vt", "soft")],
  qs=[
    C("basic", "When measuring gravitational acceleration with a simple pendulum, how should its length be measured?",
      "The string length plus the bob's radius",
      ["The string length only", "The string length plus the bob's diameter", "The string length minus the bob's radius"],
      "Pendulum length is the distance from the suspension point to the center of the bob, equal to string length plus bob radius. Measuring only the string makes l too small; adding the diameter makes it too large."),
    N("basic", "A pendulum completes 30 full oscillations in a measured time of 54.0 s. What is its period in seconds? (Enter the number only.)", "1.8",
      "T = t/n = 54.0/30 = 1.8 s. Timing several complete oscillations and averaging reduces random error in the period measurement.",
      "54.0/30"),
    N("standard", "A student varies pendulum length l, measures the corresponding period T, and plots T² against l. The graph is a straight line through the origin with slope 4.00 s²/m. Take π² = 9.86. What is the local gravitational acceleration in m/s²? (Round to two decimal places and enter the number only.)", "9.86",
      "From T² = (4π²/g)l, the slope is k = 4π²/g, so g = 4π²/k = 4 × 9.86/4.00 = 9.86 m/s². The graph method reduces random error more effectively than calculating from a single data point.",
      "round(4*9.86/4.00,2)"),
    C("standard", "A student uses the string length l′, without adding the bob's radius, as the pendulum length and plots T² against l′. What feature will the graph have?",
      "A positive y-intercept and unchanged slope; the calculated g is unaffected",
      ["A negative y-intercept and unchanged slope; the calculated g is unaffected", "It still passes through the origin but has a smaller slope, giving a larger g", "A positive y-intercept and steeper slope, giving a smaller g"],
      "The true length is l = l′ + r, so T² = (4π²/g)(l′ + r). When l′ = 0, T² = 4π²r/g > 0, giving a positive y-intercept. The slope remains 4π²/g, so the measured g is unchanged."),
  ])

T("forced_resonance", "Motion and interactions", "conceptual",
  "In real oscillations, resistance gradually reduces the amplitude; this is called damped oscillation. An oscillation driven by a periodic force is forced oscillation. Once steady, its frequency equals the driving frequency, regardless of the natural frequency. When the driving frequency equals the system's natural frequency, the amplitude is greatest; this is resonance.",
  ["Distinguish natural frequency, driving frequency, and forced-oscillation frequency", "Describe the resonance curve and the condition for resonance", "Apply the resonance condition to simple real-world problems and explain how resonance is used or prevented"],
  [("S1.2.3", "exact")],
  pre=[("shm_describe", "hard"), ("shm_force_energy", "soft"), ("J:sound_feature", "soft")],
  qs=[
    C("basic", "An object undergoes forced oscillation under a periodic driving force. Once the motion is steady, what is its oscillation frequency?",
      "The driving frequency",
      ["The object's natural frequency", "The sum of the driving and natural frequencies", "The greater of the driving and natural frequencies"],
      "Once steady, forced oscillation occurs at the driving frequency, regardless of the object's natural frequency. Resonance occurs only when the two frequencies are equal."),
    N("basic", "A simple pendulum has a natural period of 0.8 s. What driving frequency, in Hz, will produce resonance? (Enter the number only.)", "1.25",
      "At resonance, driving frequency equals natural frequency: f = 1/T = 1/0.8 = 1.25 Hz.",
      "1/0.8"),
    C("standard", "The driving-force magnitude stays constant while its frequency f increases from far below to far above the natural frequency. How does the amplitude of forced oscillation change?",
      "It first increases, then decreases; the amplitude is greatest when f equals the natural frequency",
      ["It increases continuously", "It decreases continuously", "It first decreases, then increases; the amplitude is smallest when f equals the natural frequency"],
      "The resonance curve has a single peak: amplitude increases as f approaches the natural frequency, is greatest when they are equal, and then decreases."),
    N("standard", "A train carriage (including its springs) has a natural frequency of 2.0 Hz. Each rail is 12.5 m long, and each wheel receives one impact at every rail joint. At what train speed, in m/s, will the carriage vibrate most strongly? (Enter the number only.)", "25",
      "The impact frequency is f = v/L. At resonance, f equals the natural frequency 2.0 Hz, so v = fL = 2.0 × 12.5 = 25 m/s (90 km/h).",
      "2.0*12.5"),
  ])
